class MealLog(db.Model):
    id         = db.Column(db.Integer, primary_key=True)
    user_id    = db.Column(db.Integer, db.ForeignKey("user.id", ondelete="CASCADE"), nullable=False)
    ogun       = db.Column(db.String(100), nullable=False)
    yemekler   = db.Column(db.Text, nullable=False)
    kalori     = db.Column(db.Float)
    protein    = db.Column(db.Float)
    karb       = db.Column(db.Float)
    yag        = db.Column(db.Float)
    # Kanonik gün anahtarı (Istanbul ISO 'YYYY-MM-DD'). NOT NULL + default: NULL
    # tarih satırları per-gün sorgularından SESSİZCE kaçardı. Tüm yazma yolları
    # zaten tarih veriyor; default yalnızca güvenlik ağı (app/timeutil tek kaynak).
    tarih      = db.Column(db.String(10), nullable=False, default=lambda: app_today().isoformat())
    source     = db.Column(db.String(20), default="manual")
    idempotency_key = db.Column(db.String(64), nullable=True)
    idempotency_fingerprint = db.Column(db.String(64), nullable=True)
    photo_key  = db.Column(db.String(300), nullable=True)  # S3 nesne anahtarı (opsiyonel)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

    # DB-seviyesi makro sağlık-kontrolü (3.8): negatif makro ASLA geçerli değildir;
    # üst tavan ise yalnızca açıkça bozuk/taşma (overflow, LLM çöpü, ör. 1e9) değerleri
    # yakalamak için CÖMERT seçildi — MealLog satırı tek bir öğünün/çok-öğeli önerinin
    # TOPLAMI olabildiğinden (app/blueprints/social.py toplamı sanitizer'dan geçmez),
    # per-serving sanitizer tavanı (3000) burada meşru toplamları reddederdi. NULL'lar
    # SQL CHECK semantiğiyle geçer (kolonlar nullable).
    __table_args__ = (
        db.CheckConstraint(
            "(kalori IS NULL OR (kalori >= 0 AND kalori <= 100000)) AND "
            "(protein IS NULL OR (protein >= 0 AND protein <= 50000)) AND "
            "(karb IS NULL OR (karb >= 0 AND karb <= 50000)) AND "
            "(yag IS NULL OR (yag >= 0 AND yag <= 50000))",
            name="ck_meal_log_macro_bounds"),
        # DB1: her beslenme sayfası user_id + tarih ile sorguluyor — kanonik en çok
        # yazılan defter; (user_id, tarih) kompozit indeksi user_id-only sorguları da
        # (leftmost prefix) karşılar.
        db.Index("ix_meal_log_user_id_tarih", "user_id", "tarih"),
        db.UniqueConstraint("user_id", "idempotency_key",
                            name="uq_meal_log_user_idempotency"),
    )

    def __repr__(self):
        return f"<MealLog {self.user_id} - {self.ogun} - {self.created_at}>"


