WORKOUT_COMPLETION_MARKER = "Antrenman tamamlandı (Pump Check)"


# ── Persisted workout-session lifecycle (Sprint 7 PR3) ───────────────────────
# The lifecycle status vocabulary. Small + explicit: ACTIVE is the only
# non-terminal state; COMPLETED/ABANDONED are terminal and immutable. "Stale" is
# a DERIVED condition of an ACTIVE session (see app/services/workout_session/),
# never a persisted status. No PAUSED — closing a browser is not a server-proven
# pause (docs/WORKOUT_STATE.md "Sprint 7 PR3").
WORKOUT_SESSION_ACTIVE = "active"
WORKOUT_SESSION_COMPLETED = "completed"
WORKOUT_SESSION_ABANDONED = "abandoned"
WORKOUT_SESSION_STATUSES = (
    WORKOUT_SESSION_ACTIVE,
    WORKOUT_SESSION_COMPLETED,
    WORKOUT_SESSION_ABANDONED,
)


def _new_session_public_id():
    """Opaque, non-guessable public id for API exposure (43 url-safe chars)."""
    return secrets.token_urlsafe(32)


class WorkoutSession(db.Model):
    """The canonical persisted workout-session (Sprint 7 PR3).

    The single server-owned source of truth for whether a workout session has
    actually started, remains active, can be safely resumed, or has terminated
    (completed via the PR2 completion authority / explicitly abandoned). A
    non-marker ``WorkoutLog`` row remains execution *evidence* only and never a
    resumable session; a client ``localStorage`` object is an untrusted cache —
    only a persisted ACTIVE row here is a resumable session.

    Identity/plan relationship is a MINIMAL SOFT reference (no TrainingPlan
    redesign, no stable plan-day ids — deferred): ``planned_training_plan_id`` is
    an intentionally un-FK'd soft pointer (so the row survives plan deletion and a
    missing plan is detectable), ``weekday_slot`` the normalized schedule slot,
    and ``plan_fingerprint`` a versioned digest of the intended workout's ordered
    exercise list (detects same-weekday regeneration). ``workout_date`` is the
    *start* local (Istanbul) date — CONTEXT, never silently rewritten at midnight;
    it is NOT the identity. The active-session invariant is (user_id, ACTIVE).
    """
    __tablename__ = "workout_session"

    id = db.Column(db.Integer, primary_key=True)
    # Opaque public identifier used in every API response/route — the sequential
    # PK is never exposed across users. No prior uuid/public_id convention in the
    # repo; PR3 introduces this one, scoped to session lifecycle.
    public_id = db.Column(db.String(64), nullable=False, default=_new_session_public_id)
    user_id = db.Column(
        db.Integer, db.ForeignKey("user.id", ondelete="CASCADE"),
        nullable=False, index=True,
    )
    status = db.Column(
        db.String(12), nullable=False,
        default=WORKOUT_SESSION_ACTIVE, server_default=WORKOUT_SESSION_ACTIVE,
    )
    # User-local (Istanbul) start date — CONTEXT for stale/relationship checks.
    workout_date = db.Column(db.String(10), nullable=False)
    # Normalized weekday/schedule slot the session was started for (plan 'gun').
    weekday_slot = db.Column(db.String(20), nullable=True)
    # 'scheduled' | 'unscheduled' — did a matching planned workout exist at start?
    source = db.Column(db.String(20), nullable=False, default="scheduled")
    # SOFT reference to the TrainingPlan active at start. Intentionally NOT a hard
    # FK: the session must outlive plan deletion/regeneration so a now-missing plan
    # is detectable. NULL for unscheduled sessions or when no plan existed.
    planned_training_plan_id = db.Column(db.Integer, nullable=True)
    # Versioned digest ("v1:<sha256hex>") of the intended workout's canonical,
    # order-preserving exercise-name list. Server-computed, never client-supplied;
    # a version/algorithm mismatch is classified safely (indeterminate).
    plan_fingerprint = db.Column(db.String(80), nullable=True)
    started_at = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)
    # Heartbeat/observability timestamp only — never gates resume (no inactivity
    # threshold in PR3).
    last_activity_at = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)
    completed_at = db.Column(db.DateTime, nullable=True)
    abandoned_at = db.Column(db.DateTime, nullable=True)
    # Bounded reason code for a terminal transition (abandon / stale resolution).
    terminal_reason = db.Column(db.String(40), nullable=True)
    # Transition version — bumped on TERMINAL transitions for lost-update safety;
    # the heartbeat is a lock-free conditional update and does NOT use it.
    version = db.Column(db.Integer, nullable=False, default=1, server_default="1")
    created_at = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)
    updated_at = db.Column(
        db.DateTime, nullable=False, default=datetime.utcnow, onupdate=datetime.utcnow,
    )

    user = db.relationship(
        "User", backref=db.backref("workout_sessions", passive_deletes=True))

    __table_args__ = (
        # THE active-session uniqueness invariant: at most one non-terminal
        # (status='active') session per user, enforced at the DB level — the single
        # concurrency-safe atomic claim (mirrors uq_pump_check_day for completion).
        # A partial unique index on user_id WHERE active: terminal rows vacate the
        # slot so a new session may start. Both SQLite (>=3.8) and PostgreSQL
        # support partial indexes; the dialect-specific `where` is emitted for each.
        db.Index(
            "uq_workout_session_active_owner", "user_id", unique=True,
            sqlite_where=text("status = 'active'"),
            postgresql_where=text("status = 'active'"),
        ),
        db.Index("uq_workout_session_public_id", "public_id", unique=True),
        db.Index("ix_workout_session_user_status", "user_id", "status"),
        db.CheckConstraint(
            "status IN ('active', 'completed', 'abandoned')",
            name="ck_workout_session_status",
        ),
    )

    def __repr__(self):
        return f"<WorkoutSession {self.user_id} {self.status} {self.workout_date}>"


class DailyActivity(db.Model):
    id              = db.Column(db.Integer, primary_key=True)
    user_id         = db.Column(db.Integer, db.ForeignKey("user.id", ondelete="CASCADE"), nullable=False, index=True)
    steps           = db.Column(db.Integer, nullable=False, default=0)
    intensity       = db.Column(db.String(20), nullable=False, default="moderate")
    calories_burned = db.Column(db.Float, nullable=False, default=0)
    distance_km     = db.Column(db.Float, nullable=False, default=0)
    duration_min    = db.Column(db.Float, nullable=False, default=0)
    date_key        = db.Column(db.String(10), nullable=False, default=lambda: app_today().isoformat())
    created_at      = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    user = db.relationship("User", backref=db.backref("daily_activities", passive_deletes=True))

    # C4: "günde tam bir satır" invariantını DB de zorlasın diye kısıt intensity
    # İÇERMEZ — eski (user_id, date_key, intensity) kısıdı, farklı intensity'li
    # iki eşzamanlı isteğin ikisinin de sil-ekle yapıp İKİ satır bırakmasına izin
    # veriyordu (log_daily_activity'deki IntegrityError-upsert dalı hiç tetiklenmeden).
    __table_args__ = (
        db.UniqueConstraint("user_id", "date_key", name="uq_daily_activity"),
    )


class UserWearableConnection(db.Model):
    id         = db.Column(db.Integer, primary_key=True)
    user_id    = db.Column(db.Integer, db.ForeignKey("user.id", ondelete="CASCADE"), nullable=False, index=True)
    provider   = db.Column(db.String(40), nullable=False)
    access_token_encrypted  = db.Column(db.Text, nullable=False)
    refresh_token_encrypted = db.Column(db.Text, nullable=True)
    token_expiry = db.Column(db.DateTime, nullable=True, index=True)
    scopes       = db.Column(db.Text, nullable=True)
    external_user_id = db.Column(db.String(120), nullable=True)
    status       = db.Column(db.String(20), nullable=False, default="connected", server_default="connected")
    last_sync_at = db.Column(db.DateTime, nullable=True)
    created_at   = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at   = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    user = db.relationship("User", backref=db.backref("wearable_connections", passive_deletes=True))

    __table_args__ = (
        db.UniqueConstraint("user_id", "provider", name="uq_wearable_connection_user_provider"),
        db.Index("ix_wearable_connection_provider", "provider"),
    )


class WearableSleepLog(db.Model):
    id       = db.Column(db.Integer, primary_key=True)
